  "terra-com-remada-alta":{name:"Terra com Remada Alta (Complexo)",category:"Costas/Pernas",equipment:"Barra / Halteres",muscles:["Isquiotibiais","Glúteo","Trapézio","Deltóide Posterior","Core"],description:"Exercício combinado: levantamento terra seguido de remada alta. Trabalha cadeia posterior completa.",steps:["Posição de terra: quadril para trás, costas retas","Puxe a barra até a cintura (terra)","Continue puxando verticalmente até o queixo (remada alta)","Retorne controlado"],tips:["Flua entre os dois movimentos","Mantenha core ativado"],videoId:"",videoId:"UN4v9JDynWA",images:["https://img.youtube.com/vi/UN4v9JDynWA/hqdefault.jpg"]},
  "elevacao-quadril-maquina":{name:"Elevação de Quadril na Máquina",category:"Glúteos",equipment:"Máquina",muscles:["Glúteo Máximo","Isquiotibiais"],description:"Hip thrust na máquina. Isolamento do glúteo máximo com carga guiada.",steps:["Costas no encosto da máquina","Pés planos no chão","Empurre o quadril para cima até extensão completa","Contraia glúteo no topo"],tips:["Contraia 1-2s no topo","Não hipersestenda a lombar"],videoId:"",videoId:"5B34iELOOGc",images:["https://img.youtube.com/vi/5B34iELOOGc/maxresdefault.jpg","https://img.youtube.com/vi/5B34iELOOGc/hqdefault.jpg"]},
  "rosca-21-barra":{name:"Rosca 21 com Barra",category:"Bíceps",equipment:"Barra EZ / Reta",muscles:["Bíceps Braquial","Braquial"],description:"Técnica de 21 repetições divididas em 3 arcos de 7 reps. Trabalha o bíceps em toda a amplitude.",steps:["7 repetições da metade inferior (fundo até 90°)","7 repetições da metade superior (90° até topo)","7 repetições completas (amplitude total)","Sem descanso entre as partes"],tips:["Use carga menor que a habitual","Controle absoluto — sem embalo","Ótimo finalizador"],videoId:"-aej3kEcNoU",images:["https://img.youtube.com/vi/-aej3kEcNoU/maxresdefault.jpg","https://img.youtube.com/vi/-aej3kEcNoU/hqdefault.jpg"]},
